'use strict';
// Prototype only: no APIs, no storage, no real money movement.
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>(n/100).toFixed(2);
let toastTimer;
function toast(t){const n=$('#prototype-toast');n.textContent=t;n.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>n.hidden=true,3500);}
function go(id){location.hash=id;}
let returnFocus;
function closeSheet(){document.querySelectorAll('.live-overlay').forEach(x=>x.remove());if(returnFocus&&document.contains(returnFocus))returnFocus.focus();}
function sheet(id,title,body,bind){closeSheet();returnFocus=document.activeElement;const layer=document.createElement('div');layer.className='mask live-overlay';layer.innerHTML=`<div class="sheet" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="h">${esc(title)}<button data-close aria-label="关闭">×</button></div>${body}</div>`;$(`#${id} .ph`).append(layer);layer.querySelector('[data-close]').onclick=closeSheet;layer.onclick=e=>{if(e.target===layer)closeSheet();};layer.onkeydown=e=>{if(e.key!=='Tab')return;const n=[...layer.querySelectorAll('button:not(:disabled),input,textarea,a[href]')];if(!n.length)return;if(e.shiftKey&&document.activeElement===n[0]){e.preventDefault();n.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===n.at(-1)){e.preventDefault();n[0].focus();}};bind?.(layer);layer.querySelector('button,input')?.focus();}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeSheet();});
document.addEventListener('click',e=>{const b=e.target.closest('[data-toast]');if(b)toast(b.dataset.toast);});
const stores={A:{name:'悦颜 · 科技园店',short:'科技园店',entity:'虹颜科技有限公司',localState:'进行中',localTitle:'本店日常储值',localTier:{p:10000,b:2000}},B:{name:'悦颜 · 南山店',short:'南山店',entity:'悦颜服务有限公司',localState:'进行中',localTitle:'南山店日常储值',localTier:{p:10000,b:2000}}};
let activeStore='A',selectedMember='8000',selectedBrand='悦颜美肤';
const people=[{name:'林女士',tail:'8000',brand:13000,local:{A:6000,B:2000},date:'2026-10-21'},{name:'陈女士',tail:'8359',brand:26000,local:{A:12000,B:null},date:'2026-10-20'},{name:'周女士',tail:'6221',brand:null,local:{A:null,B:null},date:''}];
const policy={enabled:true,ratio:20,paid:100000,bonus:20000,days:365,balance:20000000,approval:true,version:2};
let brandTiers=[{p:5000,b:1000},{p:10000,b:3000},{p:20000,b:5000}],brandActive=true;
let localDraft={name:'本店日常储值',p:10000,b:2000,from:'2026-10-21',to:'2026-11-20',store:'A',policyVersion:2};
let billState=0,settlementScope='BRAND',reportStore='A';
const outstanding={A:48000,B:2000};
function kv(k,v){return `<div class="frow"><span class="k">${esc(k)}</span><span class="v">${v}</span></div>`;}
function setStore(key){activeStore=key;closeSheet();const s=stores[key];document.querySelectorAll('[data-store-name]').forEach(x=>x.textContent=s.name);document.querySelectorAll('#s06 .group .frow,#s23 .group .frow,#s30 .group .frow').forEach(r=>{const k=r.querySelector('.k'),v=r.querySelector('.v');if(!k||!v)return;if(k.textContent==='经营主体'||k.textContent==='结算主体')v.textContent=s.entity;if(k.textContent==='门店发行方'||k.textContent==='发行方'&&r.closest('#s23'))v.textContent=s.short+'储值';});$('#local-name').value=s.localTitle;$('#local-title').textContent=s.localTitle;$('#local-status').textContent=s.localState;$('#local-status').className='chip '+(s.localState==='进行中'?'ok':'warn');$('#local-tier-label').textContent=`充¥${money(s.localTier.p)}送¥${money(s.localTier.b)}`;$('#s09 h3').textContent=s.short;renderMembers();renderPerson();renderRecords();renderStoreSnapshot();if(settlementScope==='STORE')renderSettlement();toast('已切换至'+s.name+'；本店储值独立，品牌范围不变');}
document.querySelectorAll('.store-switch').forEach(b=>b.onclick=()=>{const id=b.closest('figure').id;sheet(id,'切换当前门店','<div class="options">'+Object.entries(stores).map(([key,s])=>`<button class="choice" data-store="${key}" aria-pressed="${key===activeStore}"><span>${s.name}<small>悦颜品牌 · 本店独立发行方</small></span><span class="radio"></span></button>`).join('')+'</div>',l=>l.querySelectorAll('[data-store]').forEach(x=>x.onclick=()=>setStore(x.dataset.store)));});
$('#brand-form').onsubmit=e=>{e.preventDefault();const name=$('#brand-name').value.trim();if(!name)return;toast('已模拟保存品牌“'+name+'”');go('s02');};
function brandPicker(){sheet('s06','选择经营品牌','<div class="options">'+['悦颜美肤','澄心护理','不关联品牌'].map(n=>`<button class="choice" data-choose-brand="${n}" aria-pressed="${n===selectedBrand}"><span>${n}<small>${n==='不关联品牌'?'本店储值仍然保留':'仅影响品牌会员和品牌储值'}</small></span><span class="radio"></span></button>`).join('')+'</div><button class="btn main" id="brand-done">确定</button>',l=>{let choice=selectedBrand;l.querySelectorAll('[data-choose-brand]').forEach(b=>b.onclick=()=>{choice=b.dataset.chooseBrand;l.querySelectorAll('[data-choose-brand]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));});l.querySelector('#brand-done').onclick=()=>{selectedBrand=choice;document.querySelector('#s06 .group a .v').textContent=choice+' ›';closeSheet();toast('已选品牌，需影响检查后生效；本店余额未迁移');};});}
document.querySelector('#s06 .group a').onclick=e=>{e.preventDefault();brandPicker();};
document.querySelectorAll('[data-brand]').forEach(b=>b.onclick=()=>{selectedBrand=b.dataset.brand;document.querySelectorAll('[data-brand]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));});
document.querySelector('#s11 .group a').onclick=e=>{e.preventDefault();sheet('s11','选择品牌','<div class="options"><button class="choice" id="choose-demo-brand" aria-pressed="true"><span>悦颜美肤<small>2家门店 · 已授权品牌发行</small></span><span class="radio"></span></button></div><p class="hint">仅列出当前账号可发行的品牌。</p>',l=>l.querySelector('#choose-demo-brand').onclick=closeSheet);};
function readMoney(input){const raw=input.value.trim();if(!/^\d+(\.\d{1,2})?$/.test(raw))return null;const n=Math.round(Number(raw)*100);return Number.isSafeInteger(n)?n:null;}
function parseTiers(id){return [...document.querySelectorAll(`#${id} .tier-edit`)].map(r=>{const v=r.querySelectorAll('input');return{p:readMoney(v[0]),b:readMoney(v[1])};});}
function tierError(t){if(!t.length)return '至少保留一个档位';if(t.some(x=>x.p===null||x.b===null||x.p<=0||x.b<0))return '实收需大于0，赠送不得小于0，金额最多两位小数';if(new Set(t.map(x=>x.p)).size!==t.length)return '实收金额相同的档位不能重复';return '';}
$('#add-tier').onclick=()=>{const box=$('#tiers');if(box.children.length>=6){toast('最多6个档位');return;}const r=document.createElement('div');r.className='tier-edit';r.innerHTML='<label>实收<input type="number" min="0.01" step="0.01" value="300" aria-label="实收金额"></label><label>赠送<input type="number" min="0" step="0.01" value="60" aria-label="赠送金额"></label><button type="button" data-remove-tier aria-label="移除档位">×</button>';box.append(r);};
document.querySelectorAll('#tiers,#local-tiers').forEach(c=>c.onclick=e=>{const b=e.target.closest('[data-remove-tier]');if(!b)return;if(c.children.length===1){toast('至少保留一个档位');return;}b.parentElement.remove();});
$('#activity-form').onsubmit=e=>{e.preventDefault();const error=$('#activity-error'),values=parseTiers('tiers'),name=$('#activity-name').value.trim(),from=$('#activity-start').value,to=$('#activity-end').value;error.textContent=tierError(values);if(error.textContent)return;if(!name||!from||!to||from>to){error.textContent='请填写活动名称和有效起止日期';return;}brandTiers=values;$('#activity-title').textContent=name;$('#s14 h3').textContent=name;$('#review-tiers').innerHTML=values.map(t=>kv('充¥'+money(t.p)+'送¥'+money(t.b),'到账¥'+money(t.p+t.b))).join('');go('s14');};
$('#publish-activity').onclick=()=>{brandActive=true;$('#activity-status').textContent='进行中';$('#activity-status').className='chip ok';$('#stop-activity').hidden=false;go('s15');toast('已模拟发布品牌活动，不影响单店发行配置');};
$('#stop-activity').onclick=()=>sheet('s15','停止品牌新储值','<p>不影响历史余额核销，也不停止门店独立储值活动。</p><button class="btn main" id="stop-brand-now">停止新储值</button>',l=>{l.querySelector('#stop-brand-now').onclick=()=>{brandActive=false;$('#activity-status').textContent='已结束';$('#activity-status').className='chip';$('#stop-activity').hidden=true;closeSheet();};});
$('#open-entity').onclick=()=>sheet('s13','选择品牌结算主体','<div class="options"><button class="choice" aria-pressed="true"><span>悦颜品牌管理有限公司<small>已授权并确认结算</small></span><span class="radio"></span></button></div><button class="btn main" id="entity-done">确定</button>',l=>{l.querySelector('#entity-done').onclick=closeSheet;});
document.querySelector('#s13 .group a').onclick=e=>{e.preventDefault();$('#open-entity').click();};
function policyIssue(d){if(!policy.enabled)return '上层已禁止门店新发行';if(d.p>policy.paid)return '单笔实收超出上层金额限制';if(d.b>policy.bonus)return '赠送金额超出上层限制';if(d.b*100>d.p*policy.ratio)return '赠送比例超出上层限制';const days=(Date.parse(d.to)-Date.parse(d.from))/86400000+1;if(days>policy.days)return '活动天数超出上层限制';return '';}
function policyLabels(){document.querySelectorAll('#s10 .frow,#s23 .frow').forEach(r=>{const k=r.querySelector('.k'),v=r.querySelector('.v');if(!k||!v)return;if(k.textContent==='生效规则')v.textContent=(policy.enabled?'允许':'禁止')+' · '+(policy.approval?'需审批':'直接发布')+' · 赠送≤'+policy.ratio+'%';if(k.textContent==='赠送比例')v.textContent='≤'+policy.ratio+'%';if(k.textContent==='单笔实收')v.textContent='≤¥'+money(policy.paid);if(k.textContent==='发布方式')v.textContent=policy.approval?'提交上层审批':'符合规则直接发布';});}
$('#policy-form').onsubmit=e=>{e.preventDefault();const ratio=Number($('#policy-ratio').value),paid=readMoney($('#policy-paid')),bonus=readMoney($('#policy-bonus')),days=Number($('#policy-days').value),balance=readMoney($('#policy-balance'));const error=$('#policy-error');if(!Number.isFinite(ratio)||ratio<0||ratio>30){error.textContent='赠送比例不能超过全局30%上限';return;}if(paid===null||paid<=0||paid>100000||bonus===null||bonus<0||bonus>30000||!Number.isInteger(days)||days<1||days>365||balance===null||balance<=0||balance>20000000){error.textContent='请输入有效限制；不能放宽全局金额、天数或余额上限';return;}error.textContent='';Object.assign(policy,{enabled:$('#policy-enabled').checked,ratio,paid,bonus,days,balance,approval:$('#policy-approval').checked,version:policy.version+1});policyLabels();toast('已模拟保存门店管控 V'+policy.version+'；历史批次未改写');go('s25');};
$('#local-form').onsubmit=e=>{e.preventDefault();const vals=parseTiers('local-tiers'),error=$('#local-error');error.textContent=tierError(vals);if(error.textContent)return;const from=$('#local-start').value,to=$('#local-end').value,name=$('#local-name').value.trim();if(!name||!from||!to||from>to){error.textContent='请填写活动名称和有效日期';return;}localDraft={name,p:vals[0].p,b:vals[0].b,from,to,store:activeStore,policyVersion:policy.version};const issue=policyIssue(localDraft);if(issue){document.querySelector('#s27 .notice').textContent=issue+'，不能发布或通过审批绕过。';const rows=$('#s27 .group').querySelectorAll('.v');if(rows.length>=4){rows[0].textContent='¥'+money(localDraft.p);rows[1].textContent='¥'+money(localDraft.b)+' · '+(localDraft.b/localDraft.p*100).toFixed(1)+'%';rows[2].textContent=policy.ratio+'% · 最多赠送¥'+money(Math.min(Math.floor(localDraft.p*policy.ratio/100),policy.bonus));}go('s27');return;}$('#s33 h3').textContent=name;$('#local-review-tier').textContent='充¥'+money(localDraft.p)+'送¥'+money(localDraft.b);$('#local-review-total').textContent='¥'+money(localDraft.p+localDraft.b);$('#local-review-mode').textContent=policy.approval?'需上层审批':'符合规则直接发布';$('#submit-local').textContent=policy.approval?'提交审批':'发布门店活动';go('s33');};
$('#fix-local-tier').onclick=()=>{const inputs=document.querySelectorAll('#local-tiers input');const p=readMoney(inputs[0])||10000;inputs[1].value=money(Math.min(Math.floor(p*policy.ratio/100),policy.bonus));go('s23');toast('已按当前上限调整，请重新检查');};
function displayLocal(s){$('#local-title').textContent=s.localTitle;$('#local-status').textContent=s.localState;$('#local-status').className='chip '+(s.localState==='进行中'?'ok':'warn');$('#local-tier-label').textContent='充¥'+money(s.localTier.p)+'送¥'+money(s.localTier.b);}
$('#submit-local').onclick=()=>{if(localDraft.store!==activeStore){toast('门店已切换，请重新检查本店活动');go('s23');return;}const issue=policyIssue(localDraft);if(issue){toast(issue);go('s23');return;}const s=stores[activeStore];s.localTitle=localDraft.name;s.localTier={p:localDraft.p,b:localDraft.b};s.localState=policy.approval?'待审批':'进行中';displayLocal(s);renderStoreSnapshot();syncDraftReview();$('#s29 h3').textContent=s.localTitle;const q=$('#s28 .group.card');q.querySelector('strong').textContent=s.short+' · '+s.localTitle;q.querySelector('.pair>span').textContent=s.localState;go('s30');toast(policy.approval?'已模拟提交审批，尚未发布':'已模拟发布门店活动');};
$('#approve-local').onclick=()=>{const issue=policyIssue(localDraft);if(issue){toast('审批复核未通过：'+issue);return;}const s=stores[localDraft.store];s.localState='进行中';if(localDraft.store===activeStore){displayLocal(s);renderStoreSnapshot();}document.querySelector('#s28 .group.card .pair>span').textContent='已通过';go('s30');toast('已模拟审批并发布，仍仅本店可用');};
$('#reject-local').onclick=()=>{const s=stores[localDraft.store];s.localState='退回修改';if(localDraft.store===activeStore){displayLocal(s);renderStoreSnapshot();}go('s30');toast('已模拟退回修改');};
function memberCard(m){const l=m.local[activeStore];return `<a href="#s17" class="group card" data-member="${m.tail}"><div class="pair"><strong>${m.name} · ${m.tail}</strong><span>品牌会员</span></div><p class="hint">门店：${l===null?'未储值':'¥'+money(l)}　品牌：${m.brand===null?'未储值':'¥'+money(m.brand)}</p></a>`;}
function renderMembers(q=''){const list=people.filter(m=>q?(m.name.includes(q)||q.endsWith(m.tail)):(m.brand!==null||m.local[activeStore]!==null));$('#member-results').innerHTML=list.length?list.map(memberCard).join(''):'<div class="group"><h3>未找到会员</h3><p class="hint">请核对信息；新增请前往会员模块。</p></div>';}
function renderPerson(){const m=people.find(x=>x.tail===selectedMember);$('#s17 h3').textContent=m.name+' · '+m.tail;$('#local-balance').textContent=m.local[activeStore]===null?'未储值':money(m.local[activeStore]);$('#brand-balance').textContent=m.brand===null?'未储值':money(m.brand);const localBlock=$('#local-balance').closest('.group');localBlock.querySelector('h3').textContent='门店储值 · 仅'+stores[activeStore].short;localBlock.querySelector('.v').textContent=stores[activeStore].short+'储值';}
$('#member-results').onclick=e=>{const c=e.target.closest('[data-member]');if(c){selectedMember=c.dataset.member;renderPerson();renderStoreSnapshot();}};
$('#member-query').oninput=()=>{const q=$('#member-query').value.trim(),box=$('#suggestions');const matches=people.filter(m=>q&&(m.name.includes(q)||m.tail.startsWith(q)));box.hidden=!matches.length;box.innerHTML=matches.map(m=>`<button class="choice" data-suggest="${m.tail}">${m.name} · ${m.tail}</button>`).join('');};
$('#suggestions').onclick=e=>{const b=e.target.closest('[data-suggest]');if(b){$('#member-query').value=b.dataset.suggest;$('#member-search').requestSubmit();}};
$('#member-search').onsubmit=e=>{e.preventDefault();$('#suggestions').hidden=true;renderMembers($('#member-query').value.trim());};
const records=[{scope:'STORE',store:'A',type:'REDEMPTION',title:'面部护理',amount:-6000,date:'2026-10-21',time:'14:30'},{scope:'STORE',store:'A',type:'RECHARGE',title:'本店日常储值',amount:12000,date:'2026-10-20',time:'16:00'},{scope:'STORE',store:'B',type:'REDEMPTION',title:'南山店服务',amount:-10000,date:'2026-10-21',time:'10:00'},{scope:'STORE',store:'B',type:'RECHARGE',title:'南山店日常储值',amount:12000,date:'2026-10-20',time:'15:00'}];
let recordType='ALL',dateFrom='',dateTo='';
function renderRecords(){const list=records.filter(r=>r.scope==='STORE'&&r.store===activeStore&&(recordType==='ALL'||r.type===recordType)&&(!dateFrom||r.date>=dateFrom)&&(!dateTo||r.date<=dateTo)).sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time));$('#records').innerHTML=list.length?list.map(r=>`<div class="group record"><div class="pair"><strong>${esc(r.title)}</strong><span class="record-amount ${r.amount>0?'plus':''}">${r.amount>0?'+':'−'}¥${money(Math.abs(r.amount))}</span></div><p class="hint">门店储值 · ${r.type==='RECHARGE'?'储值':'核销'}</p><span class="record-date">${r.date} ${r.time}</span></div>`).join(''):'<div class="group"><h3>暂无符合条件的记录</h3></div>';$('#time-summary').textContent=dateFrom||dateTo?`${dateFrom||'不限'} 至 ${dateTo||'不限'}`:'';}
document.querySelectorAll('[data-record]').forEach(b=>b.onclick=()=>{recordType=b.dataset.record;document.querySelectorAll('[data-record]').forEach(x=>x.classList.toggle('on',x===b));renderRecords();});
$('#open-time').onclick=()=>sheet('s18','筛选时间',`<label class="field"><span>开始日期</span><input type="date" id="date-from" value="${dateFrom}"></label><label class="field"><span>结束日期</span><input type="date" id="date-to" value="${dateTo}"></label><p id="date-error" class="error"></p><div class="acts"><button class="btn sec" id="date-reset">重置</button><button class="btn main" id="date-apply">确定</button></div>`,l=>{l.querySelector('#date-reset').onclick=()=>{l.querySelector('#date-from').value=l.querySelector('#date-to').value='';};l.querySelector('#date-apply').onclick=()=>{const f=l.querySelector('#date-from').value,t=l.querySelector('#date-to').value;if(f&&t&&f>t){l.querySelector('#date-error').textContent='结束日期不能早于开始日期';return;}dateFrom=f;dateTo=t;closeSheet();renderRecords();};});
$('#open-recharge').onclick=()=>{let scope='STORE',picked=-1;const draw=()=>{let options=scope==='STORE'?[stores[activeStore].localTier]:brandTiers;const active=scope==='STORE'?stores[activeStore].localState==='进行中'&&policy.enabled:brandActive;const body='<div class="tabline"><button data-recharge-scope="STORE" class="'+(scope==='STORE'?'on':'')+'">门店储值</button><button data-recharge-scope="BRAND" class="'+(scope==='BRAND'?'on':'')+'">品牌储值</button></div><p class="hint">'+(scope==='STORE'?'仅'+stores[activeStore].short+'可用':'悦颜品牌全部门店通用')+'</p><div class="options">'+(active?options.map((t,i)=>`<button class="choice" data-tier="${i}" aria-pressed="false"><span>充¥${money(t.p)}送¥${money(t.b)}<small>到账¥${money(t.p+t.b)}</small></span><span class="radio"></span></button>`).join(''):'<p class="notice">暂无可办理活动；待审批、已停止或上层禁止新储值。</p>')+'</div>'+(active?'<button class="btn main" id="charge-submit">选择方案</button>':'');sheet('s17','选择储值方案',body,l=>{l.querySelectorAll('[data-recharge-scope]').forEach(b=>b.onclick=()=>{scope=b.dataset.rechargeScope;picked=-1;draw();});l.querySelectorAll('[data-tier]').forEach(b=>b.onclick=()=>{picked=Number(b.dataset.tier);l.querySelectorAll('[data-tier]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));l.querySelector('#charge-submit').textContent=(scope==='STORE'?'本店储值':'品牌储值')+' ¥'+money(options[picked].p);});const submit=l.querySelector('#charge-submit');if(submit)submit.onclick=()=>{if(picked<0){toast('请选择方案');return;}const t=options[picked],m=people.find(x=>x.tail===selectedMember);if(scope==='STORE'){const issue=policyIssue({...t,from:'2026-10-21',to:'2026-10-21'});if(issue){toast('办理校验：'+issue);return;}if(outstanding[activeStore]+t.p+t.b>policy.balance){toast('超过本店未消费余额上限');return;}m.local[activeStore]=(m.local[activeStore]||0)+t.p+t.b;outstanding[activeStore]+=t.p+t.b;}else m.brand=(m.brand||0)+t.p+t.b;records.unshift({scope,store:activeStore,type:'RECHARGE',title:scope==='STORE'?stores[activeStore].localTitle:$('#activity-title').textContent,amount:t.p+t.b,date:'2026-10-21',time:'15:00'});closeSheet();renderPerson();renderMembers();renderRecords();renderStoreSnapshot();toast('演示：'+(scope==='STORE'?'本店':'品牌')+'账户已到账 ¥'+money(t.p+t.b)+'；另一账户未变');};});};draw();};
$('#open-use-account').onclick=()=>{let choice='';const m=people.find(x=>x.tail===selectedMember),s=stores[activeStore];sheet('s32','选择核销账户','<div class="options">'+[{key:'STORE',title:'门店储值',sub:'仅'+s.short,balance:m.local[activeStore]||0},{key:'BRAND',title:'品牌储值',sub:'悦颜品牌通用',balance:m.brand||0}].map(x=>`<button class="choice" data-wallet="${x.key}" aria-pressed="false"><span>${x.title}<small>${x.sub} · 可用¥${money(x.balance)}</small></span><span class="radio"></span></button>`).join('')+'</div><p class="hint">本次应付¥50，一次仅选一个账户，不自动组合余额。</p><button class="btn main" id="use-wallet-next">继续订单授权</button>',l=>{l.querySelectorAll('[data-wallet]').forEach(b=>b.onclick=()=>{choice=b.dataset.wallet;l.querySelectorAll('[data-wallet]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));});l.querySelector('#use-wallet-next').onclick=()=>{if(!choice){toast('请选择账户');return;}const available=choice==='STORE'?(m.local[activeStore]||0):(m.brand||0);if(available<5000){toast('所选账户余额不足，请选择其他账户');return;}closeSheet();toast('演示：已选'+(choice==='STORE'?'门店':'品牌')+'账户，后续沿用订单消费者授权；未扣款');};});};
function renderSettlement(){const n=$('#settlement-content');$('#settle-brand').classList.toggle('on',settlementScope==='BRAND');$('#settle-store').classList.toggle('on',settlementScope==='STORE');if(settlementScope==='STORE'){n.innerHTML='<div class="group"><h3>门店储值 · '+stores[reportStore].short+'</h3>'+kv('发行方',stores[reportStore].short+'储值')+kv('结算主体',stores[reportStore].entity)+kv('使用范围','仅本店')+'<button class="text-link" id="select-report-store">选择对账门店 ›</button>'+'</div><div class="group"><h3>本店对账</h3>'+kv('实收',reportStore==='A'?'¥600.00':'¥100.00')+kv('核销',reportStore==='A'?'¥240.00':'¥100.00')+kv('同主体内部对账','无需生成跨主体付款单')+'</div><p class="notice">不包含品牌发行方资金或品牌跨店清分。</p>';$('#select-report-store').onclick=()=>sheet('s21','选择对账门店','<div class="options">'+Object.entries(stores).map(([key,st])=>'<button class="choice" data-finance-store="'+key+'"><span>'+st.name+'<small>'+st.entity+'</small></span></button>').join('')+'</div>',l=>l.querySelectorAll('[data-finance-store]').forEach(b=>b.onclick=()=>{reportStore=b.dataset.financeStore;closeSheet();renderSettlement();}));return;}n.innerHTML='<div class="group"><h3>悦颜品牌储值</h3>'+kv('结算主体','悦颜品牌管理有限公司')+kv('示例账期','2026年10月')+'</div><div class="group"><h3>品牌主体清分</h3><div class="metrics"><div><span>应结算</span><b>2,000.00</b></div><div><span>已结算</span><b>'+(billState===3?'2,000.00':'800.00')+'</b></div><div><span>待结算</span><b>'+(billState===3?'0.00':'1,200.00')+'</b></div></div></div><a class="group card" href="#s22"><div class="pair"><strong>悦颜服务有限公司</strong><span>'+(billState===3?'已结算':'待处理')+'</span></div><p class="hint">南山店 · ¥1,200.00</p></a>';}
$('#settle-brand').onclick=()=>{settlementScope='BRAND';renderSettlement();};$('#settle-store').onclick=()=>{settlementScope='STORE';renderSettlement();};
function updateBill(){const labels=['待核对','待付款','待收款确认','已结算'];$('#bill-status').textContent=labels[billState];$('#bill-status').className='chip '+(billState===3?'ok':'warn');$('#bill-action').hidden=billState===3;$('#bill-action').textContent=['确认账单','登记付款','确认收款'][billState]||'已结算';$('#bill-dispute').hidden=billState!==0;$('#bill-note').textContent=['演示角色：收款方财务。核对账单后确认。','演示角色：结算方财务。实际付款后登记凭据。','演示角色：收款方财务。独立核对实际到账。','收款方已确认到账，保留原凭据及确认记录。'][billState];if(billState===3)$('#bill-paid').textContent='¥1,200.00';renderSettlement();}
$('#bill-action').onclick=()=>{if(billState===0){billState=1;updateBill();return;}if(billState===1){sheet('s22','登记付款凭据','<p class="hint">悦颜服务有限公司 · ¥1,200.00</p><label class="field"><span>实际付款日期</span><input type="date" id="paid-date" value="2026-10-21"></label><label class="field"><span>凭据编号</span><input id="paid-reference" placeholder="实际转账凭据"></label><p class="hint">只登记，不执行转账。</p><button class="btn main" id="save-paid">登记付款</button>',l=>l.querySelector('#save-paid').onclick=()=>{const r=l.querySelector('#paid-reference').value.trim();if(!r||!l.querySelector('#paid-date').value){toast('请填写日期和凭据');return;}$('#bill-receipt').innerHTML='<div class="group"><h3>付款凭据</h3><p>'+esc(r)+'</p><p class="hint">待收款方核对</p></div>';billState=2;closeSheet();updateBill();});return;}sheet('s22','确认实际收款','<p>请以收款方财务身份确认¥1,200.00已实际到账。</p><button class="btn main" id="confirm-received">已核对，确认收款</button>',l=>l.querySelector('#confirm-received').onclick=()=>{billState=3;closeSheet();updateBill();toast('模拟结算完成，未发生真实划款');});};
$('#bill-dispute').onclick=()=>sheet('s22','提出异议','<label class="field"><span>异议原因</span><textarea id="dispute-reason"></textarea></label><button class="btn main" id="send-dispute">提交异议</button>',l=>l.querySelector('#send-dispute').onclick=()=>{if(!l.querySelector('#dispute-reason').value.trim()){toast('请填写异议原因');return;}closeSheet();$('#bill-status').textContent='异议处理中';$('#bill-action').hidden=$('#bill-dispute').hidden=true;$('#bill-note').textContent='原单金额保留，待双方核对，不直接覆盖账单。';});
renderMembers();renderPerson();renderRecords();updateBill();policyLabels();

function renderStoreSnapshot(){const values=activeStore==='A'?['600.00','120.00','720.00','240.00','480.00','0.00']:['100.00','20.00','120.00','100.00','20.00','0.00'];document.querySelectorAll('#s31 .metrics b').forEach((n,i)=>n.textContent=values[i]);document.querySelector('#s31 .group:last-child .v').textContent=stores[activeStore].entity;document.querySelectorAll('#s10 .group .frow').forEach(r=>{if(r.querySelector('.k')?.textContent==='发行方')r.querySelector('.v').textContent=stores[activeStore].short+'储值';});const activityValues=activeStore==='A'?['600.00','120.00','240.00','480.00']:['100.00','20.00','100.00','20.00'];document.querySelectorAll('#s30 .metrics b').forEach((n,i)=>n.textContent=activityValues[i]);const useGroups=document.querySelectorAll('#s32 .group');const person=people.find(x=>x.tail===selectedMember);if(useGroups.length>1){useGroups[0].querySelector('.v').textContent=person.name+' · '+person.tail;const cards=useGroups[1].querySelectorAll('.card');cards[0].querySelector('.pair>span').textContent='¥'+money(person.local[activeStore]||0);cards[0].querySelector('.hint').textContent='仅'+stores[activeStore].short+'可用';cards[1].querySelector('.pair>span').textContent='¥'+money(person.brand||0);}const c=$('#s10 .group.card');c.querySelector('strong').textContent=stores[activeStore].localTitle;c.querySelector('.pair>span').textContent=stores[activeStore].localState;}
document.querySelectorAll('[data-report-store]').forEach(a=>a.onclick=()=>setStore(a.dataset.reportStore));
renderStoreSnapshot();

function syncDraftReview(){const st=stores[localDraft.store];document.querySelectorAll('#s29 .frow').forEach(r=>{const k=r.querySelector('.k')?.textContent,v=r.querySelector('.v');if(!v)return;const values={'申请门店':st.short,'结算主体':st.entity,'档位':'充¥'+money(localDraft.p)+'送¥'+money(localDraft.b),'赠送比例':(localDraft.b/localDraft.p*100).toFixed(1)+'% / 上限'+policy.ratio+'%','单笔金额':'¥'+money(localDraft.p)+' / 上限¥'+money(policy.paid),'规则版本':'门店发行 V'+policy.version};if(k in values)v.textContent=values[k];});}
